    function input(event){if(!current()){revoke();return;}const target=event.target,entry=state.dialog;if(target.hasAttribute('data-bm-row-text')&&canEdit()){const row=state.draft.items.find(row=>row.row_key===target.dataset.bmRowText);if(row?.message_type==='text'){row.text=target.value;const count=host.querySelector('[data-bm-row-count="'+row.row_key+'"]');if(count)count.textContent=number(row.text.length)+' / 1.000 caracteres';}return;}const name=target.dataset.bmField;if(!name)return;if(name==='interval_seconds'&&canEdit()){state.draft.interval_seconds=target.value;return;}if(entry?.type==='add'&&!entry.adding&&['manual','text','contact_q'].includes(name)){if(name==='contact_q')entry.contactFilters.q=target.value;else entry[name]=target.value;if(name==='text'){const count=entry.element.querySelector('[data-bm-text-count]');if(count)count.textContent=number(entry.text.length)+' / 1.000 caracteres. O texto será enviado como foi escrito.';}return;}if(name==='confirmation'&&entry?.type==='operation'&&!state.busy){entry.confirmation=target.value;const confirm=entry.element.querySelector('[data-bm-action="confirm"]');if(confirm)confirm.disabled=!entry.checked||entry.confirmation!=='ENVIAR'||state.operation?.preview.eligible===0||Date.parse(state.operation?.preview.expires_at)<=Date.now();}else if(name==='q')state.filters.q=target.value;else if(name==='recipient_q')state.recipientFilters.q=target.value;}
